  "AI-Coding-Guide-Zh/docs/openclaw/11-常见问题FAQ.md",
];
const out = [];
for (const f of files) {
  const g = await tools.bash({ command: `wc -l "${f}"; grep -n '^#' "${f}" | head -60`, description: "List headings and length" });
