const docs = [
  { code: "OC-06", cat: "openclaw", title: "OpenClaw技能系统指南", file: "AI-Coding-Guide-Zh/docs/openclaw/06-技能系统指南.md", out: "oc-06.json", hint: "技能（Skill）是什么、Skills vs Tools、常用命令、内置技能分类、SKILL.md 格式、自定义技能、权限、编排、技能市场、调试、生命周期、常见问题" },
  { code: "OC-07", cat: "openclaw", title: "OpenClaw记忆系统指南", file: "AI-Coding-Guide-Zh/docs/openclaw/07-记忆系统指南.md", out: "oc-07.json", hint: "三层记忆架构、记忆源、sqlite-vec 向量存储、Embedding 提供商、Compaction、上下文窗口与滑动窗口、USER.md、记忆工具 memory_search/memory_get、RAG 知识库、记忆增删改查、隐私安全、调优、多用户隔离、Dreaming、最佳实践、常见问题" },
  { code: "OC-08", cat: "openclaw", title: "OpenClaw多Agent协作指南", file: "AI-Coding-Guide-Zh/docs/openclaw/08-多Agent协作指南.md", out: "oc-08.json", hint: "什么是 Agent、为什么多个 Agent、Agent 架构与目录、角色定义与配置、SOUL.md、不同模型、Agent 间通信 Sessions、共享数据、消息路由与 bindings、任务分发策略、实战案例、转交、工具权限、性能监控、调试、常见问题" },
  { code: "OC-09", cat: "openclaw", title: "OpenClaw-Docker部署指南", file: "AI-Coding-Guide-Zh/docs/openclaw/09-Docker部署指南.md", out: "oc-09.json", hint: "为什么用 Docker、环境准备与系统要求、官方镜像与构建、docker-compose 基础版/进阶版、环境变量、数据持久化 Volumes、网络、生产实践 Nginx/TLS/健康检查、云平台部署、Agent 沙箱、自动更新、性能调优、备份恢复、常见问题排查、速查卡" },
  { code: "OC-10", cat: "openclaw", title: "OpenClaw安全配置指南", file: "AI-Coding-Guide-Zh/docs/openclaw/10-安全配置指南.md", out: "oc-10.json", hint: "为什么安全第一、安全分层模型与零信任、API Key 管理（环境变量/.env/密钥服务/轮换/泄露检测）、沙箱系统与工具 Allow/Deny、权限控制 Gateway 认证/DM Pairing/访问控制、文件与网络安全 TLS/绑定地址/防火墙、消息平台安全、日志审计、最佳实践清单、常见威胁、事故演练、数据最小化、合规、事件响应、常见问题" },
  { code: "OC-11", cat: "openclaw", title: "OpenClaw常见问题FAQ", file: "AI-Coding-Guide-Zh/docs/openclaw/11-常见问题FAQ.md", out: "oc-11.json", hint: "安装配置、消息平台、模型和 AI、技能和工具、部署运维、记忆系统、安全隐私、中国用户、社区贡献、其他、版本升级迁移等十大类问题" },
];

const schema = `{
  "code": "OC-06",
  "category": "openclaw",
  "fileTitle": "OpenClaw技能系统指南",
  "deck": "幻灯片主标题",
  "slides": [
    {"layout":"cover","title":"...","subtitle":"...","kicker":"Vibe Coding 学习系列 · OC-06"},
    {"layout":"section","title":"...","subtitle":"..."},
    {"layout":"bullets","title":"...","bullets":["...","..."],"notes":"讲稿提示(可省略)"},
    {"layout":"cards","title":"...","cards":[{"title":"...","desc":"..."}]},
    {"layout":"table","title":"...","headers":["..."],"rows":[["..."]]},
    {"layout":"steps","title":"...","steps":[{"title":"...","desc":"..."}]},
    {"layout":"quote","title":"...","subtitle":"..."},
    {"layout":"end","title":"...","subtitle":"..."}
  ]
}`;

function buildPrompt(d) {
  return `你是内容编辑，要为一篇中文教程文档生成一份用于演示的 PPT 内容 JSON。

工作目录：/Users/oyamahappa/Documents/Agent/DSH
要读的文档：${d.file}
输出文件：vibe-coding-ppt/tutorials-content/${d.out}

元信息（必须原样使用）：
- code: ${d.code}
- category: ${d.cat}
- fileTitle: ${d.title}
- 封面 kicker 固定为：Vibe Coding 学习系列 · ${d.code}

文档内容要点范围参考（仅为方向，实际以读到的原文为准）：${d.hint}

执行步骤：
1. 用 grep 工具（pattern 为 ^#{1,3} ）读取该文档的标题结构，了解全篇。
2. 用 read 工具分段读取（offset/limit，每次约 200-300 行）覆盖全文重点章节。文档很长，必须分段读，不要臆测。
3. 抽取关键事实：命令、版本号（如 v2026.x）、数字、功能名必须与原文完全一致，不得编造；没有把握的内容不写。
4. 设计 10-14 张幻灯片，推荐结构：cover → section → 若干内容页（bullets/cards/table/steps/quote 混用）→ end。
5. 用 write 工具写入 JSON（UTF-8，纯 JSON，不要加 markdown 代码围栏）。

严格 schema（顶层必须有 code/category/fileTitle/deck/slides）：
${schema}

硬性约束：
- 幻灯片总数 10-14 张；必须包含 1 张 cover（kicker 固定）和 1 张 end。
- 每张 bullets 的 bullets 数组最多 5 条，每条总长度不超过 42 个字符（中文和英文字母都各算 1）。
- cards 每张 3-4 个；每个 desc 简明。
- steps 每段 3-4 步。
- table 最多 5 列、最多 6 行数据（不含表头）。
- 全部使用简体中文；命令、版本号、技术术语保留英文。
- 用新手能懂的类比解释术语（例如把向量检索比作“按意思找书”，把沙箱比作“玻璃房”）。
- 不要出现超出文档的事实；不要写“本文档”之类空话。
- 不要用 markdown 代码围栏包裹 JSON。

写完后用 read 工具复查该 JSON 的开头和结尾，确认能被 JSON.parse 解析。然后回报：
- 文件路径
- deck 标题
- slides 数量
- 是否已确认可 JSON.parse`;
}

const calls = docs.map(d =>
  tools.subagent({ description: `生成 ${d.code} PPT JSON`, prompt: buildPrompt(d), run_in_background: true })
);
const results = await Promise.all(calls);
return JSON.stringify({ docs: docs.map(d => d.code), results }, null, 2);
", "description": "Launch six subagents for six docs", "timeoutMs": 120000}

