const fs = await import("node:fs");
const dir = "vibe-coding-ppt/tutorials-content";
const codes = ["OC-06","OC-07","OC-08","OC-09","OC-10","OC-11"];
const titles = {
  "OC-06":"OpenClaw技能系统指南","OC-07":"OpenClaw记忆系统指南","OC-08":"OpenClaw多Agent协作指南",
  "OC-09":"OpenClaw-Docker部署指南","OC-10":"OpenClaw安全配置指南","OC-11":"OpenClaw常见问题FAQ"
};
const lines = [];
const allErrs = [];
for (const code of codes) {
  const p = `${dir}/${code.toLowerCase()}.json`;
  let doc;
  try { doc = JSON.parse(fs.readFileSync(p, "utf8")); }
  catch (e) { allErrs.push(`${code}: JSON.parse 失败 ${e.message}`); continue; }
  const errs = [];
  if (doc.code !== code) errs.push("code mismatch");
  if (doc.category !== "openclaw") errs.push("category mismatch");
  if (doc.fileTitle !== titles[code]) errs.push("fileTitle mismatch: " + doc.fileTitle);
  if (!doc.deck) errs.push("no deck");
  if (!Array.isArray(doc.slides)) errs.push("no slides");
  const s = doc.slides;
  if (s.length < 10 || s.length > 14) errs.push("slide count " + s.length);
  if (s[0].layout !== "cover") errs.push("first not cover");
  const kick = `Vibe Coding 学习系列 · ${code}`;
  if (s[0].kicker !== kick) errs.push("kicker=" + s[0].kicker);
  if (s[s.length-1].layout !== "end") errs.push("last not end");
  s.forEach((sl, i) => {
    if (sl.layout === "bullets") {
      if (!Array.isArray(sl.bullets) || sl.bullets.length > 5) errs.push(`slide${i} bullets`);
      (sl.bullets||[]).forEach((b,j)=>{ if(String(b).length>42) errs.push(`slide${i}b${j} len${String(b).length}`); });
    }
    if (sl.layout === "cards" && (!sl.cards || sl.cards.length<3 || sl.cards.length>4)) errs.push(`slide${i} cards`);
    if (sl.layout === "steps" && (!sl.steps || sl.steps.length<3 || sl.steps.length>4)) errs.push(`slide${i} steps`);
    if (sl.layout === "table") {
      if (!sl.headers || sl.headers.length>5) errs.push(`slide${i} cols`);
      if (!sl.rows || sl.rows.length>6) errs.push(`slide${i} rows`);
      (sl.rows||[]).forEach((r,j)=>{ if(r.length!==sl.headers.length) errs.push(`slide${i}r${j}`); });
    }
    if (!["cover","section","bullets","cards","table","steps","quote","end"].includes(sl.layout)) errs.push(`slide${i} layout ${sl.layout}`);
  });
  const layouts = s.map(x=>x.layout);
  if (errs.length) allErrs.push(`${code}: ${errs.join("; ")}`);
  lines.push(`${code} | ${doc.fileTitle} | ${doc.deck} | ${s.length} 张 | ${[...new Set(layouts)].join("/")}`);
}
return JSON.stringify({ files: lines, errors: allErrs }, null, 2);
